/* ---------------------------------------------------------------------- */
/*  Scoring engine (mirrors the original score.py weights/tiers)          */
/* ---------------------------------------------------------------------- */

const IMG_CAIRO = "data:image/jpeg;base64,";
const IMG_DRAGON_RYUJIN = "data:image/jpeg;base64,";
const IMG_SOLACE = "data:image/jpeg;base64,";
const IMG_PARCHMENT_BG = "data:image/jpeg;base64,";
const IMG_STAR_SPARK = "data:image/jpeg;base64,";
const IMG_MOON_STAR = "data:image/jpeg;base64,";

const clamp = (n, lo, hi) => Math.max(lo, Math.min(hi, n));

function computeScores({ sleep, water, screen, exercise }) {
  const sleepScore = clamp(100 - 14 * Math.abs(sleep - 8), 0, 100);
  const waterScore = clamp(100 - 22 * Math.abs(water - 2.75), 0, 100);
  const screenScore = clamp(100 - 9 * Math.max(0, screen - 2), 0, 100);
  const exerciseScore = clamp((exercise / 45) * 100, 0, 100);
  const total = Math.round(
    sleepScore * 0.3 + exerciseScore * 0.3 + waterScore * 0.2 + screenScore * 0.2
  );
  return { sleepScore, waterScore, screenScore, exerciseScore, total };
}

function tierLine(total, weakestLabel) {
  if (total >= 90) return "Harmony is inscribed upon you.";
  if (total >= 75) return "Steady balance; little quarrel with you.";
  if (total >= 55) return `Faint strain. ${weakestLabel}`;
  if (total >= 35) return `Discord stirs. ${weakestLabel}`;
  return `An ill omen weighs heavy. ${weakestLabel}`;
}

const WEAK_REASONS = {
  sleepScore: "Rest is the thin thread — mind the hours you grant it.",
  waterScore: "The river runs low — drink and be replenished.",
  screenScore: "The eye is bound too long to the glowing glass.",
  exerciseScore: "The body has gone unmoved — give it labor.",
};

/* ---------------------------------------------------------------------- */
/*  Storage helpers                                                       */
/* ---------------------------------------------------------------------- */

const STORAGE_KEY = "wellness-tablet-entries";

async function loadEntries() {
  try {
    const res = await window.storage.get(STORAGE_KEY);
    if (!res) return [];
    return JSON.parse(res.value);
  } catch {
    return [];
  }
}

async function saveEntries(entries) {
  try {
    await window.storage.set(STORAGE_KEY, JSON.stringify(entries));
    return true;
  } catch {
    return false;
  }
}

const NAME_STORAGE_KEY = "wellness-tablet-name";

async function loadName() {
  try {
    const res = await window.storage.get(NAME_STORAGE_KEY);
    if (!res) return "";
    return res.value || "";
  } catch {
    return "";
  }
}

async function saveName(name) {
  try {
    await window.storage.set(NAME_STORAGE_KEY, name);
    return true;
  } catch {
    return false;
  }
}

function timeGreeting() {
  const h = new Date().getHours();
  if (h < 5) return "Rest well, seeker";
  if (h < 12) return "Good morning, seeker";
  if (h < 17) return "Good afternoon, seeker";
  if (h < 21) return "Good evening, seeker";
  return "Rest well, seeker";
}

