/* ---------------------------------------------------------------------- */
/*  Derived stats                                                         */
/* ---------------------------------------------------------------------- */

function deriveStats(entries) {
  const sorted = [...entries].sort((a, b) => a.date.localeCompare(b.date));

  let streak = 0;
  for (let i = sorted.length - 1; i >= 0; i--) {
    if (sorted[i].total >= 75) streak++;
    else break;
  }

  const points = sorted.reduce((sum, e) => sum + e.total, 0);

  let consistency = 0;
  if (sorted.length > 0) {
    const first = new Date(sorted[0].date);
    const last = new Date(sorted[sorted.length - 1].date);
    const daySpan = Math.max(1, Math.round((last - first) / 86400000) + 1);
    consistency = clamp(Math.round((sorted.length / daySpan) * 100), 0, 100);
  }

  const streakComponent = clamp((Math.min(streak, 14) / 14) * 100, 0, 100);
  const disciplineLevel = Math.round(streakComponent * 0.6 + consistency * 0.4);

  const badges = {
    firstInscription: sorted.length >= 1,
    threeDayEmber: streak >= 3,
    sevenDayBlaze: streak >= 7,
    perfectMark: sorted.some((e) => e.total === 100),
    centurion: points >= 500,
    wellRounded: sorted.some(
      (e) =>
        e.sleepScore >= 80 &&
        e.waterScore >= 80 &&
        e.screenScore >= 80 &&
        e.exerciseScore >= 80
    ),
  };

  return { sorted, streak, points, consistency, streakComponent, disciplineLevel, badges };
}

const BADGE_DEFS = [
  { key: "firstInscription", label: "First Inscription", desc: "Seal your first day" },
  { key: "threeDayEmber", label: "Three-Day Ember", desc: "3-day streak at balance" },
  { key: "sevenDayBlaze", label: "Seven-Day Blaze", desc: "7-day streak at balance" },
  { key: "perfectMark", label: "Perfect Mark", desc: "Score a full 100" },
  { key: "centurion", label: "Centurion of Points", desc: "500 points, all-time" },
  { key: "wellRounded", label: "Well-Rounded", desc: "80+ on all four in one day" },
];

