function todayISO() {
  return new Date().toISOString().slice(0, 10);
}

export default function WellnessTablet() {
  const [tab, setTab] = useState("dashboard");
  const [theme, setTheme] = useState("dark");
  const [entries, setEntries] = useState([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [saveMsg, setSaveMsg] = useState("");
  const [name, setName] = useState("");
  const [nameDraft, setNameDraft] = useState("");
  const [editingName, setEditingName] = useState(false);

  const [date, setDate] = useState(todayISO());
  const [sleep, setSleep] = useState(7.5);
  const [water, setWater] = useState(2.5);
  const [screen, setScreen] = useState(3);
  const [exercise, setExercise] = useState(30);

  useEffect(() => {
    (async () => {
      const [loaded, loadedName] = await Promise.all([loadEntries(), loadName()]);
      setEntries(loaded);
      setName(loadedName);
      setNameDraft(loadedName);
      setLoading(false);
    })();
  }, []);

  const commitName = useCallback(async () => {
    const trimmed = nameDraft.trim().slice(0, 30);
    setName(trimmed);
    setNameDraft(trimmed);
    setEditingName(false);
    await saveName(trimmed);
  }, [nameDraft]);

  const preview = useMemo(
    () => computeScores({ sleep, water, screen, exercise }),
    [sleep, water, screen, exercise]
  );

  const weakestKey = useMemo(() => {
    const { sleepScore, waterScore, screenScore, exerciseScore } = preview;
    const parts = { sleepScore, waterScore, screenScore, exerciseScore };
    return Object.keys(parts).reduce((a, b) => (parts[a] <= parts[b] ? a : b));
  }, [preview]);

  const seal = useCallback(async () => {
    setSaving(true);
    const scores = computeScores({ sleep, water, screen, exercise });
    const entry = { date, sleep, water, screen, exercise, ...scores };
    const next = [...entries.filter((e) => e.date !== date), entry];
    setEntries(next);
    const ok = await saveEntries(next);
    setSaving(false);
    setSaveMsg(ok ? "Sealed upon the tablet." : "The seal did not hold — try again.");
    setTimeout(() => setSaveMsg(""), 2500);
  }, [entries, date, sleep, water, screen, exercise]);

  const stats = useMemo(() => deriveStats(entries), [entries]);
  const stageIdx = stageIndexForLevel(stats.disciplineLevel);
  const currentStage = STAGES[stageIdx];
  const badgeCount = BADGE_DEFS.length;
  const earnedBadgeCount = BADGE_DEFS.filter((b) => stats.badges[b.key]).length;
  const todayEntry = entries.find((e) => e.date === todayISO());

  const chartData = stats.sorted.map((e) => ({
    date: e.date.slice(5),
    total: e.total,
    sleep: e.sleepScore,
    water: e.waterScore,
    screen: e.screenScore,
    exercise: e.exerciseScore,
  }));

  const isLight = theme === "light";
  const chartAxisColor = isLight ? "#6b4a12" : "#c9a227";
  const chartGridColor = isLight ? "#a68f5e" : "#3a2f1a";
  const chartTooltipStyle = {
    background: isLight ? "#ede0bd" : "#1a1208",
    border: `1px solid ${isLight ? "#a3651a" : "#d4af37"}`,
    color: isLight ? "#3b2c14" : "#e8c878",
  };
  const chartLegendColor = isLight ? "#3b2c14" : "#e8c878";

  const embers = useMemo(
    () =>
      Array.from({ length: 9 }, (_, i) => ({
        left: (i * 37 + 6) % 100,
        delay: (i * 1.7) % 9,
        duration: 7 + ((i * 2.3) % 6),
        size: 2 + (i % 3),
      })),
    []
  );

  return (
    <div className={`wt-root ${theme === "light" ? "wt-light" : ""}`}>
      <IconDefs />
      <style>{CSS}</style>

      <div className="wt-bg-parchment" aria-hidden="true" />
      <div className="wt-bg-overlay" aria-hidden="true" />
      <div className="wt-embers" aria-hidden="true">
        {embers.map((e, i) => (
          <span
            key={i}
            className="wt-ember"
            style={{
              left: `${e.left}%`,
              width: `${e.size}px`,
              height: `${e.size}px`,
              animationDelay: `${e.delay}s`,
              animationDuration: `${e.duration}s`,
            }}
          />
        ))}
      </div>

      <button
        type="button"
        className="wt-theme-toggle"
        onClick={() => setTheme((t) => (t === "dark" ? "light" : "dark"))}
        aria-label={theme === "dark" ? "Switch to light parchment" : "Switch to dark ambience"}
        title={theme === "dark" ? "Switch to light parchment" : "Switch to dark ambience"}
      >
        <span className="wt-theme-toggle-track">
          <span className="wt-theme-toggle-glyph wt-theme-toggle-moon">☾</span>
          <span className="wt-theme-toggle-glyph wt-theme-toggle-sun">☀</span>
          <span className="wt-theme-toggle-thumb" />
        </span>
      </button>

      <header className="wt-header">
        <div className="wt-header-glyphs" aria-hidden="true">𓂀 𓆣 𓋹 𓊹 𓁶</div>
        <h1>The Wellness Tablet</h1>
        <p className="wt-sub">An oracle of sleep, water, screen &amp; labor</p>
      </header>

      <nav className="wt-tabs">
        <button
          className={tab === "dashboard" ? "wt-tab active" : "wt-tab"}
          onClick={() => setTab("dashboard")}
        >
          Dashboard
        </button>
        <button
          className={tab === "inscribe" ? "wt-tab active" : "wt-tab"}
          onClick={() => setTab("inscribe")}
        >
          Inscribe the Day
        </button>
        <button
          className={tab === "chronicle" ? "wt-tab active" : "wt-tab"}
          onClick={() => setTab("chronicle")}
        >
          The Chronicle
        </button>
      </nav>

      {loading ? (
        <div className="wt-loading">Unsealing the tablet…</div>
      ) : tab === "dashboard" ? (
        <section className="wt-panel wt-dashboard">
          <div className="wt-dashboard-greet">
            <div className="wt-dashboard-greet-line">
              {timeGreeting()}
              {name ? `, ${name}` : ""}
            </div>
            {editingName ? (
              <div className="wt-dashboard-name-edit">
                <input
                  type="text"
                  className="wt-name-input"
                  value={nameDraft}
                  onChange={(e) => setNameDraft(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && commitName()}
                  placeholder="Your name"
                  autoFocus
                  maxLength={30}
                />
                <button className="wt-name-save" onClick={commitName}>
                  Save
                </button>
              </div>
            ) : (
              <button
                className="wt-dashboard-name-btn"
                onClick={() => {
                  setNameDraft(name);
                  setEditingName(true);
                }}
              >
                {name ? "Change name" : "Add your name"}
              </button>
            )}
          </div>

          <div className="wt-dashboard-status">
            {todayEntry ? (
              <>
                <div className="wt-dashboard-status-mark">{todayEntry.total}</div>
                <div className="wt-dashboard-status-line">
                  Today is sealed upon the tablet.
                </div>
              </>
            ) : (
              <>
                <div className="wt-dashboard-status-line">
                  The tablet awaits today's inscription.
                </div>
                <button className="wt-dashboard-cta" onClick={() => setTab("inscribe")}>
                  Inscribe the Day
                </button>
              </>
            )}
          </div>

          <div className="wt-stat-row">
            <div className="wt-stat-card">
              <div className="wt-stat-num">{stats.streak}</div>
              <div className="wt-stat-label">Day Streak</div>
            </div>
            <div className="wt-stat-card">
              <div className="wt-stat-num">{stats.points}</div>
              <div className="wt-stat-label">Points</div>
            </div>
            <div className="wt-stat-card">
              <div className="wt-stat-num">{stats.disciplineLevel}</div>
              <div className="wt-stat-label">Discipline</div>
            </div>
          </div>

          <div className="wt-dashboard-stage">
            <div className="wt-dashboard-stage-icon">
              <StageIcon stageKey={currentStage.key} active={true} />
            </div>
            <div className="wt-dashboard-stage-text">
              <div className="wt-dashboard-stage-label">{currentStage.label}</div>
              <div className="wt-dashboard-stage-sub">
                {earnedBadgeCount} of {badgeCount} badges earned
              </div>
            </div>
          </div>

          <button className="wt-dashboard-cta wt-dashboard-cta-secondary" onClick={() => setTab("chronicle")}>
            View the Chronicle
          </button>
        </section>
      ) : tab === "inscribe" ? (
        <section className="wt-panel">
          <div className="wt-field">
            <label>Date</label>
            <input type="date" value={date} onChange={(e) => setDate(e.target.value)} />
          </div>

          <SliderField
            label="Sleep"
            unit="hours"
            value={sleep}
            min={0}
            max={12}
            step={0.5}
            onChange={setSleep}
          />
          <SliderField
            label="Water"
            unit="liters"
            value={water}
            min={0}
            max={5}
            step={0.25}
            onChange={setWater}
          />
          <SliderField
            label="Screen"
            unit="hours"
            value={screen}
            min={0}
            max={12}
            step={0.5}
            onChange={setScreen}
          />
          <SliderField
            label="Exercise"
            unit="minutes"
            value={exercise}
            min={0}
            max={120}
            step={5}
            onChange={setExercise}
          />

          <div className="wt-preview">
            <div className="wt-preview-mark">{preview.total}</div>
            <div className="wt-preview-line">
              {tierLine(preview.total, WEAK_REASONS[weakestKey])}
            </div>
          </div>

          <button className="wt-seal-btn" onClick={seal} disabled={saving}>
            {saving ? "Sealing…" : "Seal This Entry"}
          </button>
          {saveMsg && <div className="wt-save-msg">{saveMsg}</div>}
        </section>
      ) : (
        <section className="wt-panel">
          {entries.length === 0 ? (
            <div className="wt-empty">
              The tablet is blank. Inscribe a day to begin the chronicle.
            </div>
          ) : (
            <>
              {/* Growth story strip */}
              <div className="wt-journey">
                <div className="wt-journey-title">Growth through discipline</div>
                <div className="wt-journey-strip">
                  {STAGES.map((s, i) => (
                    <div
                      key={s.key}
                      className={`wt-journey-stage ${i === stageIdx ? "current" : ""} ${
                        i < stageIdx ? "past" : i > stageIdx ? "future" : ""
                      }`}
                    >
                      <div className="wt-journey-icon-wrap">
                        <StageIcon stageKey={s.key} active={i <= stageIdx} />
                      </div>
                      <div className="wt-journey-label">{s.label}</div>
                      {i < STAGES.length - 1 && <div className="wt-journey-connector" />}
                    </div>
                  ))}
                </div>
                <div className="wt-journey-footnote">
                  Discipline Level {stats.disciplineLevel}/100 — streak component{" "}
                  {Math.round(stats.streakComponent)}/100, consistency {stats.consistency}/100
                </div>
              </div>

              {/* Stat row */}
              <div className="wt-stat-row">
                <div className="wt-stat-card">
                  <div className="wt-stat-num">{stats.streak}</div>
                  <div className="wt-stat-label">Day Streak</div>
                </div>
                <div className="wt-stat-card">
                  <div className="wt-stat-num">{stats.points}</div>
                  <div className="wt-stat-label">Points</div>
                </div>
                <div className="wt-stat-card">
                  <div className="wt-stat-num">{stats.disciplineLevel}</div>
                  <div className="wt-stat-label">Discipline</div>
                </div>
              </div>

              {/* Badges */}
              <div className="wt-badges">
                {BADGE_DEFS.map((b, i) => (
                  <React.Fragment key={b.key}>
                    <div
                      className={`wt-badge ${stats.badges[b.key] ? "earned" : "locked"}`}
                      title={b.desc}
                    >
                      <div className="wt-badge-shield">
                        <div className="wt-badge-mark">{stats.badges[b.key] ? "✦" : "✧"}</div>
                      </div>
                      <div className="wt-badge-label">{b.label}</div>
                    </div>
                    {i < BADGE_DEFS.length - 1 && (
                      <div
                        className={`wt-badge-connector ${stats.badges[b.key] ? "earned" : ""}`}
                      />
                    )}
                  </React.Fragment>
                ))}
              </div>

              {/* Charts */}
              <div className="wt-chart-block">
                <div className="wt-chart-title">Overall Mark Over Time</div>
                <ResponsiveContainer width="100%" height={220}>
                  <LineChart data={chartData} margin={{ top: 10, right: 16, left: -16, bottom: 0 }}>
                    <CartesianGrid stroke={chartGridColor} strokeDasharray="3 3" />
                    <XAxis dataKey="date" stroke={chartAxisColor} fontSize={11} />
                    <YAxis stroke={chartAxisColor} fontSize={11} domain={[0, 100]} />
                    <Tooltip contentStyle={chartTooltipStyle} />
                    <ReferenceLine y={75} stroke="#d4af37" strokeDasharray="6 4" label={{ value: "Balance", fill: "#d4af37", fontSize: 11 }} />
                    <Line type="monotone" dataKey="total" stroke="#f5a623" strokeWidth={2.5} dot={{ r: 3 }} />
                  </LineChart>
                </ResponsiveContainer>
              </div>

              <div className="wt-chart-block">
                <div className="wt-chart-title">Each Measure, Trending</div>
                <ResponsiveContainer width="100%" height={220}>
                  <LineChart data={chartData} margin={{ top: 10, right: 16, left: -16, bottom: 0 }}>
                    <CartesianGrid stroke={chartGridColor} strokeDasharray="3 3" />
                    <XAxis dataKey="date" stroke={chartAxisColor} fontSize={11} />
                    <YAxis stroke={chartAxisColor} fontSize={11} domain={[0, 100]} />
                    <Tooltip contentStyle={chartTooltipStyle} />
                    <Legend wrapperStyle={{ fontSize: 11, color: chartLegendColor }} />
                    <Line type="monotone" dataKey="sleep" stroke="#7fb3d5" strokeWidth={1.8} dot={false} />
                    <Line type="monotone" dataKey="water" stroke="#4fc3c9" strokeWidth={1.8} dot={false} />
                    <Line type="monotone" dataKey="screen" stroke="#c97b63" strokeWidth={1.8} dot={false} />
                    <Line type="monotone" dataKey="exercise" stroke="#9ccc65" strokeWidth={1.8} dot={false} />
                  </LineChart>
                </ResponsiveContainer>
              </div>
            </>
          )}
        </section>
      )}

      {/* Corner avatar */}
      <div className={`wt-avatar ${stageIdx === 4 ? "ascended" : ""}`}>
        <div className="wt-avatar-ring">
          <StageIcon stageKey={currentStage.key} active={true} />
        </div>
        <div className="wt-avatar-caption">
          {currentStage.label} · {stats.disciplineLevel || 0}
        </div>
      </div>
    </div>
  );
}

function SliderField({ label, unit, value, min, max, step, onChange }) {
  return (
    <div className="wt-field">
      <label>
        {label} <span className="wt-unit">({unit})</span>
        <span className="wt-value">{value}</span>
      </label>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(parseFloat(e.target.value))}
      />
    </div>
  );
}

